    dfs = []
    for f in files:
        try:
            df = pd.read_csv(f, encoding='latin-1')
            df['source_file'] = f
            dfs.append(df)
        except Exception as e:
            pass
    return pd.concat(dfs, ignore_index=True)

def process(fraud_other_reports, identity_theft_reports) -> pd.DataFrame:
    # Merge both datasets on State
    merged = fraud_other_reports[['State', 'Num_Reports']].merge(
        identity_theft_reports[['State', 'Num_Reports']],
        on='State', suffixes=('_fraud_other', '_identity_theft')
    )
    merged['Total_Reports'] = merged['Num_Reports_fraud_other'] + merged['Num_Reports_identity_theft']
    return merged.sort_values('Total_Reports', ascending=False).reset_index(drop=True)

