def load() -> pd.DataFrame:
    import glob
    import os

    results = []
    files = glob.glob("data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv")

    # Find California file
    ca_file = None
    for f in files:
        basename = os.path.basename(f).lower()
        if 'california' in basename or basename == 'ca.csv':
            ca_file = f
            break

    # If not found, check all filenames
    if ca_file is None:
        filenames = sorted([os.path.basename(f) for f in files])
        return pd.DataFrame({'all_files': filenames})

    # Load and inspect the California file
    with open(ca_file, 'r', encoding='latin-1') as fh:
        lines = fh.readlines()

    return pd.DataFrame({'line_num': range(len(lines)), 'content': [l.strip() for l in lines]})
